(* [comment removed for export] *)
Definition ipf_frame (m1 : mem) (spa ff : Z) (jt : list byte) (p bsz : Z) (bb : list byte) (vl nm : list cell) : Prop :=
  rw_cells bsegs m1 (spa + 120) [CB 24 jt]
  /\ rw_cells bsegs m1 (spa + 144) [C8 (wz p)]
  /\ rw_cells bsegs m1 (spa + 152) vl /\ cells_size vl = 16%nat
  /\ rw_cells bsegs m1 (spa + 168) nm /\ cells_size nm = 16%nat
  /\ rw_cells bsegs m1 (ff + 32) [C8 (wz bsz); CB 4096 bb] /\ 0 <= bsz <= 4096.

(* [comment removed for export] *)
(* [comment removed for export] *)
  Lemma ipf_after_scr : forall (LF : list fframe) (m m1 m2 : mem) (sp : word) (spa : Z) (gsz : nat) (gj : list byte)
      (ra s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word)
      (P IN E p0 : Z) (bs : list byte) (c c1 c2 : pcore) (pad7 pad2 : list byte) (q : Z) (ecs1 ecs2 : list cell) (g g2 : bool)
      (lo shi ff fp last : Z) (h0 h1 h2 h3 : word) (shb j96 jr jh : list byte) (XS XS2 : list (Z * Z))
      (jt : list byte) (p' bsz : Z) (bb : list byte) (vl nm : list cell),
    ipf_ctx H LF m m1 sp spa gsz gj ra s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v P IN E p0 bs c1 pad7 pad2 q ecs1 g
            lo shi ff fp h0 h1 h2 h3 shb j96 jr jh XS ->
    ipf_frame m1 spa ff jt p' bsz bb vl nm ->
    ipf_bpure sp spa gsz P IN E lo shi c p0 last bs ->
    Forall (fs_scratch H ((7, ff, fp) :: LF)) XS2 ->
    munch ([(lo, spa); (P, P + 80); (E, E + 24); (AG_HTTP_CAT, AG_HTTP_CAT + 64)] ++ XS2) m1 m2 ->
    wmono bsegs m1 m2 -> mem_inv bsegs m2 -> stk bsegs m2 lo spa ->
    rw_cells bsegs m2 P (ParserCoreCells c2 pad7 pad2) -> rw_cells bsegs m2 E ecs2 -> AHttpCat m2 g2 -> AXStatics2 m2 ->
    as_RFS H ((7, ff, fp) :: LF) m2 -> ACONST m2 -> stack0 m2 lo shi ->
       ipf_ctx H LF m m2 sp spa gsz gj ra s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v P IN E p0 bs c2 pad7 pad2 q ecs2 g2
               lo shi ff fp h0 h1 h2 h3 shb j96 jr jh (XS ++ XS2)
