  Lemma ipf_after_pf : forall (LF : list fframe) (m m1 m2 : mem) (sp : word) (spa : Z) (gsz : nat) (gj : list byte)
      (ra s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word)
      (P IN E p0 : Z) (bs : list byte) (c c1 : pcore) (pad7 pad2 : list byte) (q : Z) (E1 : ecv) (ecs2 : list cell) (g g2 : bool)
      (lo shi ff fp last : Z) (h0 h1 h2 h3 : word) (shb j96 jr jh : list byte) (XS : list (Z * Z))
      (jt : list byte) (p1 bsz p2 bsz2 : Z) (bb bb2 : list byte) (vl nm vl2 nm2 : list cell),
    ipf_ctx H LF m m1 sp spa gsz gj ra s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v P IN E p0 bs c1 pad7 pad2 q (ErrCodeCells E1) g
            lo shi ff fp h0 h1 h2 h3 shb j96 jr jh XS ->
    ipf_frame m1 spa ff jt p1 bsz bb vl nm ->
    ipf_bpure sp spa gsz P IN E lo shi c p0 last bs ->
    munch [(lo, spa); (spa + 144, spa + 184); (ff + 32, ff + 32 + 4104); (E, E + 24); (AG_HTTP_CAT, AG_HTTP_CAT + 64)] m1 m2 ->
    wmono bsegs m1 m2 -> mem_inv bsegs m2 -> stk bsegs m2 lo spa ->
    rw_cells bsegs m2 (spa + 144) [C8 (wz p2)] -> rw_cells bsegs m2 (spa + 152) vl2 -> cells_size vl2 = 16%nat ->
    rw_cells bsegs m2 (spa + 168) nm2 -> cells_size nm2 = 16%nat ->
    rw_cells bsegs m2 (ff + 32) [C8 (wz bsz2); CB 4096 bb2] -> 0 <= bsz2 <= 4096 ->
