(* [comment removed for export] *)
  Lemma ipf_after_in : forall (LF : list fframe) (m m1 m2 : mem) (sp : word) (spa : Z) (gsz : nat) (gj : list byte)
      (ra s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word)
      (P IN E p0 : Z) (bs : list byte) (c c1 : pcore) (pad7 pad2 : list byte) (q q2 : Z) (E1 : ecv) (g : bool)
      (lo shi ff fp last : Z) (h0 h1 h2 h3 : word) (shb j96 jr jh : list byte) (XS : list (Z * Z))
      (jt : list byte) (p1 bsz : Z) (bb : list byte) (vl nm : list cell),
    ipf_ctx H LF m m1 sp spa gsz gj ra s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v P IN E p0 bs c1 pad7 pad2 q (ErrCodeCells E1) g
            lo shi ff fp h0 h1 h2 h3 shb j96 jr jh XS ->
    ipf_frame m1 spa ff jt p1 bsz bb vl nm ->
    ipf_bpure sp spa gsz P IN E lo shi c p0 last bs ->
    munch [(IN, IN + 8)] m1 m2 -> wmono bsegs m1 m2 -> mem_inv bsegs m2 ->
    rw_cells bsegs m2 IN [C8 (wz q2)] ->
       ipf_ctx H LF m m2 sp spa gsz gj ra s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v P IN E p0 bs c1 pad7 pad2 q2 (ErrCodeCells E1) g
               lo shi ff fp h0 h1 h2 h3 shb j96 jr jh XS
